#!/usr/bin/env bash
export S4E_ONE_RUNNER_FIXTURE="gate arm ${0##*/}: the harness's run, extension-ref and extension-check verbs over a scratch suite outside corpus/, not a board (CEO-547)"
# test_gate_extension_refs_are_marked_graded_and_never_recut.sh -- THE EXTENSION REF (Lon 2026-10-02 15:5x CDT, in-chat to the coo,
# verbatim: "So mark it passing. We need a concept now of extensions which will NOT have their REF generated by oracle. But generated
# by us here." · "In this case use CSNOBOL4 to gen the ORD tests. Mark the test as not generated by the SPITBOL oracle."). A test of an
# extension the suite's one oracle lacks (VDIFFER: sbl -bf ERROR 022) takes its ref from a NAMED other oracle, is marked in a ledger beside
# the data (ALL.extensions.tsv beside a rung suite, EXTENSIONS.tsv beside a package) and stays in the denominator. WHAT THIS GATE HOLDS,
# over a scratch two-entry rung suite and a scratch one-program package outside corpus/ (CEO-547), through corpus_suite_harness.py:
# ⛔ THE FIXTURE'S EXTENSION IS VDIFFER, A CSNOBOL4 BUILTIN sbl -bf LACKS. It was ORD until the oracle swap of 2026-10-03T00:56Z (CEO-1438)
# compiled ORD into sbl: extension-ref then rightly refused the ORD entry as answered by the suite's own oracle and 13 of 15 arms red.
# Re-check the premise on every swap: sbl -bf must print ERROR 022 for the fixture's program and csnobol4 its value.
# (1) extension-ref without --apply writes nothing; with --apply it cuts the VDIFFER entry's ref from csnobol4 (A) and writes a ledger row
#     whose sha is the ref's; it REFUSES rc=2 on the entry the suite's own oracle answers identically (no extension needed);
# (2) run grades the VDIFFER entry against that ref -- PASS in m3, IN the denominator -- and prints EXTENSION_REF_COUNT 1 with its row;
# (3) FAIL-ONCE, the same entry declared OUTSIDE instead (the pre-cure shape) leaves the graded denominator, so arm 2 reds on it;
# (4) run REFUSES rc=2 on a ref edited after its row was cut (a stale sha), on a name both in the ledger and the outside list, and on
#     a ref_oracle accessor the harness does not know;
# (5) extension-check passes a package ledger, and REFUSES rc=2 on a stale sha and on a program also named in EXCLUDED.tsv;
# (6) capture-oracle-refs REFUSES rc=2 to overwrite a package program the ledger names.
# rc 2 when sbl, csnobol4 or the binary is missing.
HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"; ROOT="$(cd "$HERE/../../SCRIP" && pwd)" || { echo "REFUSE(2): no SCRIP beside harness at $HERE/../../SCRIP (a port root) -- this gate measures SCRIP and cannot from here"; exit 2; }; cd "$ROOT" || { echo "⛔ REFUSE(2): cannot cd to SCRIP root" >&2; exit 2; }
. "$HERE/lib_gate.sh" 2>/dev/null || { echo "⛔ REFUSE(2): no lib_gate.sh" >&2; exit 2; }
. "$HERE/lib_oracle_flags.sh" 2>/dev/null || { echo "⛔ REFUSE(2): no lib_oracle_flags.sh" >&2; exit 2; }
GATE_NAME=extension_refs_are_marked_graded_and_never_recut; gate_parse_args "$@" 2>/dev/null || true
H="$HERE/corpus_suite_harness.py"
[ -x "$ROOT/scrip" ] || { echo "⛔ GATE REFUSE(2) [$GATE_NAME]: no ./scrip -- run make"; exit 2; }
gate_require_fresh "$ROOT" src "$ROOT/scrip" "$ROOT/out/libscrip_rt.so" || exit 2
sbl_correctness_bin >/dev/null 2>&1 || { echo "⛔ GATE REFUSE(2) [$GATE_NAME]: no SPITBOL oracle"; exit 2; }
csnobol4_bin >/dev/null 2>&1 || { echo "⛔ GATE REFUSE(2) [$GATE_NAME]: no csnobol4 -- the extension oracle this gate cuts with"; exit 2; }
export S4E_PROGRESS_OFF=1 S4E_SEAT="${S4E_SEAT:-coo}"
T=$(mktemp -d); trap 'rm -rf "$T"' EXIT
banner() { local t=" $1 $2"; printf '*%s%s\n' "$(printf '%*s' $((79 - ${#t})) '' | tr ' ' -)" "$t"; }
suite() {  # <dir> <ext ref line> -- a two-entry rung suite: ext_entry (VDIFFER, which sbl lacks) and plain_entry
    mkdir -p "$1"
    { banner 1 ext_entry; printf "\tOUTPUT = VDIFFER('A','B')\nEND\n"; banner 2 plain_entry; printf "\tOUTPUT = 'hi'\nEND\n"; } > "$1/ALL.sno"
    { banner 1 ext_entry; printf '%s\n' "$2"; banner 2 plain_entry; printf 'hi\n'; } > "$1/ALL.ref"
}
red=0; n=0
arm() { n=$((n+1)); if [ "$2" = "$3" ]; then echo "  ok   $n $1: $2"; else echo "  FAIL $n $1: got '$2' want '$3'"; red=$((red+1)); fi; }
ruling="gate fixture: Lon 2026-10-02, a CSNOBOL4 extension takes its ref from CSNOBOL4"
xref() { python3 "$H" extension-ref "$@" --oracle csnobol4_bin --feature VDIFFER --ruling "$ruling" > "$T/xref.out" 2>&1; echo $?; }
run() { python3 "$H" run "$1/ALL.sno" "$1/ALL.ref" --modes m3 > "$T/run.out" 2>&1; echo $?; }
field() { grep -oE "(^| )$1=[0-9]+" "$T/run.out" | tail -1 | sed 's/^ //'; }
graded() { echo "$(field m3_pass) $(field m3_fail)"; }

# (1) the writer
S="$T/rungs"; suite "$S" "vdiffer_unimplemented.sno(7) : ERROR 022 -- undefined function called"
before="$(md5sum < "$S/ALL.ref")"
arm "extension-ref dry run" "$(xref "$S/ALL.sno" ext_entry) $( [ "$(md5sum < "$S/ALL.ref")" = "$before" ] && [ ! -e "$S/ALL.extensions.tsv" ] && echo unchanged || echo written)" "0 unchanged"
arm "extension-ref --apply" "$(xref "$S/ALL.sno" ext_entry --apply) $(awk '/ext_entry$/{getline; print; exit}' "$S/ALL.ref") $(grep -c $'^ext_entry\tcsnobol4_bin\tVDIFFER\t' "$S/ALL.extensions.tsv" 2>/dev/null)" "0 A 1"
arm "extension-ref refuses where the suite's oracle agrees" "$(xref "$S/ALL.sno" plain_entry --apply)" "2"

# (2) graded, in the denominator, printed
rc=$(run "$S")
[ "$rc" = 2 ] && { echo "⛔ GATE REFUSE(2) [$GATE_NAME]: the harness refused the clean fixture:"; tail -5 "$T/run.out"; exit 2; }
arm "run grades the extension entry" "rc=$rc $(graded)" "rc=0 m3_pass=2 m3_fail=0"
arm "run prints the mark" "$(grep -c '^EXTENSION_REF ext_entry ref_oracle=csnobol4_bin feature=VDIFFER' "$T/run.out") $(grep -oE '^EXTENSION_REF_COUNT [0-9]+' "$T/run.out")" "1 EXTENSION_REF_COUNT 1"
arm "the board line carries extension=" "$(grep '^SUITE_BOARD ' "$T/run.out" | grep -oE '(^| )extension=[0-9]+' | sed 's/^ //')" "extension=1"

# (3) fail-once: the pre-cure shape, the entry OUTSIDE and no ledger, grades one entry, not two
P="$T/pre"; suite "$P" "A"; printf 'ext_entry\tORACLE_REFUSES\tsbl -bf ERROR 022\n' > "$P/ALL.outside.tsv"
run "$P" >/dev/null
arm "fail-once: OUTSIDE leaves the graded denominator" "$(graded) $(grep '^SUITE_BOARD ' "$T/run.out" | grep -oE '(^| )extension=[0-9]+' | sed 's/^ //')" "m3_pass=1 m3_fail=0 extension=0"

# (4) the refusals
X="$T/stale"; cp -r "$S" "$X"; sed -i 's/^A$/B/' "$X/ALL.ref"
arm "run refuses a stale sha" "$(run "$X") $(grep -c 'no longer hashes' "$T/run.out")" "2 1"
X="$T/both"; cp -r "$S" "$X"; printf 'ext_entry\tORACLE_REFUSES\tsbl -bf ERROR 022\n' > "$X/ALL.outside.tsv"
arm "run refuses ledger and outside both" "$(run "$X") $(grep -c 'also stand in the outside list' "$T/run.out")" "2 1"
X="$T/acc"; cp -r "$S" "$X"; sed -i 's/\tcsnobol4_bin\t/\tsnobol4_on_path\t/' "$X/ALL.extensions.tsv"
arm "run refuses an unknown accessor" "$(run "$X") $(grep -c 'not one of' "$T/run.out")" "2 1"

# (5) a package ledger
K="$T/pkg"; mkdir -p "$K"; printf "\tOUTPUT = VDIFFER('A','B')\nEND\n" > "$K/vd.sno"; printf 'stale\n' > "$K/vd.ref"
arm "extension-ref --apply on a package program" "$(xref "$K" vd.sno --apply) $(cat "$K/vd.ref")" "0 A"
python3 "$H" extension-check "$K" > "$T/chk.out" 2>&1; arm "extension-check passes" "$? $(grep -oE '^EXTENSION_REF_COUNT [0-9]+' "$T/chk.out")" "0 EXTENSION_REF_COUNT 1"
X="$T/pkg2"; cp -r "$K" "$X"; printf 'B\n' > "$X/vd.ref"
python3 "$H" extension-check "$X" >/dev/null 2>&1; arm "extension-check refuses a stale sha" "$?" "2"
X="$T/pkg3"; cp -r "$K" "$X"; printf 'vd.sno\tNOT_SPITBOL_DIALECT\tVDIFFER\n' > "$X/EXCLUDED.tsv"
python3 "$H" extension-check "$X" >/dev/null 2>&1; arm "extension-check refuses a program also EXCLUDED" "$?" "2"

# (6) the oracle's capture never overwrites it
python3 "$H" capture-oracle-refs "$K" --force > "$T/cap.out" 2>&1; arm "capture-oracle-refs refuses an extension program" "$? $(grep -c 'carries an EXTENSION REF' "$T/cap.out") $(cat "$K/vd.ref")" "2 1 A"

echo "population: $n arm(s) over a 2-entry rung suite and a 1-program package, mode m3, oracles sbl -bf (the suite's) and csnobol4 (the extension's)"
if [ "$red" -eq 0 ]; then echo "GATE OK [$GATE_NAME]: an extension ref is cut by its named oracle, marked, graded in the denominator, printed, and never re-cut"; gate_stamp 2>/dev/null; exit 0; fi
echo "⛔ GATE FAIL [$GATE_NAME]: $red of $n arm(s) red"; gate_stamp 2>/dev/null; exit 1
